      "mainEntity": [
        {
          "@type": "Question",
          "name": "Can I buy a new hot-water unit before the assessment?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You can ask about a proposed product, but do not assume it suits the existing supply, connections or installation location. Confirm equipment compatibility, required trades and the full installation scope before purchase or approval."
          }
        },
        {
          "@type": "Question",
          "name": "Are gas and heat-pump systems automatically included?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Give the system type and proposed task. Any gas, refrigeration or other specialist component must be checked against the appropriate service capability and authorisation before work is accepted."
          }
        },
        {
          "@type": "Question",
          "name": "Why has my hot water suddenly stopped working?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Several supply, heating or plumbing faults can interrupt hot water. The system type and affected outlets guide assessment. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Why is there hot water at some taps but not at the shower?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A shower-only temperature problem can involve its fitting or mixing arrangement rather than failure of the whole heater. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Why might an electric hot water system trip a safety switch?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A heater or its electrical supply may be faulty. Do not bypass the safety switch or keep resetting it. Read the explanation."
          }
        },
        {
          "@type": "Question",
          "name": "Do I need to diagnose the problem first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Describe the observable change and property context. We inspect the affected area on site to establish the cause and confirm the repair scope. If more access is needed, we agree it with you first."
          }
        },
        {
          "@type": "Question",
          "name": "Can I send photos?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach a hazard, remove covers or dismantle equipment to take a photo."
          }
        },
        {
          "@type": "Question",
          "name": "Is a hot-water problem plumbing or electrical?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It can be either, depending on the system and symptom. Describe the issue rather than trying to diagnose it yourself."
          }
        },
        {
          "@type": "Question",
          "name": "What should I send with a hot-water enquiry?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Include the property address, unit location, what changed, affected fixtures and any safely readable unit information."
          }
        },
        {
          "@type": "Question",
          "name": "Can I remove the cover to check the unit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Do not remove covers or handle wiring."
          }
        },
        {
          "@type": "Question",
          "name": "Can you assess repair and replacement options at the same visit?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We assess the existing system and explain the repair scope. If replacement needs to be considered, we discuss equipment and connection requirements as a separate option in the written quote. No replacement is assumed from the initial enquiry."
          }
        }
      ]
    }
